import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= nodes; v++) adj.add(new ArrayList<>());
        for (long[] e : edges) {
            adj.get((int) e[0]).add((int) e[1]);
            adj.get((int) e[1]).add((int) e[0]);
        }
        for (List<Integer> lst : adj) Collections.sort(lst);
        long total = 0;
        for (long[] e : edges) {
            List<Integer> x = adj.get((int) e[0]);
            List<Integer> y = adj.get((int) e[1]);
            int i = 0, j = 0;
            while (i < x.size() && j < y.size()) {
                int p = x.get(i), q = y.get(j);
                if (p == q) {
                    total++;
                    i++;
                    j++;
                } else if (p < q) {
                    i++;
                } else {
                    j++;
                }
            }
        }
        System.out.println(total / 3);
    }
}
